use lg_core::Date;
use lg_report::group::Granularity;
use lg_report::FiscalCalendar;

#[test]
fn disc_l11() {
    let c = FiscalCalendar::new(4).unwrap();
    assert_eq!(c.period(Date::ymd(2024, 4, 10), Granularity::Year).to_string(), "FY2024");
    assert_eq!(c.period(Date::ymd(2024, 4, 1), Granularity::Quarter).to_string(), "FY2024-T1");
    let jan = FiscalCalendar::default();
    assert_eq!(jan.period(Date::ymd(2024, 1, 2), Granularity::Year).to_string(), "FY2024");
}
